    AwakerID = 54117,
    ShowInAwakerDate = 1,
    AwakerVoiceTab = "Daily",
    TriggerTime = {
      "ClickAwaker"
    },
    AwakerVoiceTitle = "Voice_60990_AwakerVoiceTitle|闲话·关于共性",
    FacialExpressionSwitch = "0,ShutEye,7,Serious",
    AwakerVoiceContent = "Voice_60990_AwakerVoiceContent|就技巧性而言，计策谋划与音乐指挥没有区别。人性，情感，欲望……它们如五线谱上的音符般清晰温顺，陈列在我眼前，跟随指挥棒的轨迹起舞。通晓了音乐，便通晓了一切。",
    AwakerVoiceResAffix = "Commonality",
    Sort = 53
  },
