  [95070] = {
    ID = 95070,
    CnID = "语音@波吕克斯好感度等级5",
    BaseSortID = 2334,
    AwakerID = 77917,
    ShowInAwakerDate = 1,
    AwakerVoiceTab = "Daily",
    TriggerTime = {
      "ClickAwaker"
    },
    AwakerVoiceTitle = "Voice_95070_AwakerVoiceTitle|同调率·五",
    FacialExpressionSwitch = "0,ShutEye",
    AwakerVoiceContent = "Voice_95070_AwakerVoiceContent|引领我、给予我光明之人啊，曾经我一直被蒙蔽在虚假的意义中，现在在您的指引下，我已找回了我真正的使命——将那些愚昧而扭曲的伪信者矫邪归正，为世间带来恒久不灭的光明。我知晓您的无私，您并不需要我的虔诚与供奉，那么就请允许我跟随在您的身边，记录下您的每一条圣言与圣行，以供于暗夜之中指引我的前路。",
