  [95063] = {
    ID = 95063,
    CnID = "语音@波吕克斯闲话2其他",
    BaseSortID = 2336,
    AwakerID = 77917,
    ShowInAwakerDate = 1,
    AwakerVoiceTab = "Daily",
    TriggerTime = {
      "ClickAwaker"
    },
    AwakerVoiceTitle = "Voice_95063_AwakerVoiceTitle|闲话·关于危机",
    FacialExpressionSwitch = "0,ShutEye",
    AwakerVoiceContent = "Voice_95063_AwakerVoiceContent|曾经所有的人都告诉我，这深渊般的黑色是我的信仰，是我将带给信徒的赐福。如今，这黑暗早已将我侵蚀，与我融为一体……可这罪孽身体里那颗跳动的心，是永远无法被侵蚀的地方。请放心，我一定会用这黑色赋予我的能力，将真正的福祉带给世人！",
    AwakerVoiceResAffix = "GossipAblation",
    Sort = 37
  },
  [95069] = {
    ID = 95069,
    CnID = "语音@波吕克斯闲话3其他",
    BaseSortID = 2337,
    AwakerID = 77917,
    ShowInAwakerDate = 1,
    AwakerVoiceTab = "Daily",
    TriggerTime = {
      "ClickAwaker"
    },
    AwakerVoiceTitle = "Voice_95069_AwakerVoiceTitle|闲话·关于弥萨格",
    FacialExpressionSwitch = "0,Serious",
    AwakerVoiceContent = "Voice_95069_AwakerVoiceContent|能够引领众人走出迷雾之人，才是真正纯银塑身的持灯者。于丽埃特口中的无罪净土，却是以教徒的累累尸骨堆砌而成。身为圣子，我会将新的福音播撒至所有值得拯救的虔信之人。",
    AwakerVoiceResAffix = "GossipCollege",
    Sort = 38
  },
  [95080] = {
    ID = 95080,
    CnID = "语音@波吕克斯闲话4其他",
    BaseSortID = 2338,
    AwakerID = 77917,
    ShowInAwakerDate = 1,
    AwakerVoiceTab = "Daily",
    TriggerTime = {
      "ClickAwaker"
    },
    AwakerVoiceTitle = "Voice_95080_AwakerVoiceTitle|闲话·喜欢的东西",
    FacialExpressionSwitch = "0,ShutEye",
    AwakerVoiceContent = "Voice_95080_AwakerVoiceContent|儿时的我一心想要飞出囚笼，那时我总认为这个只会给人带来痛苦的地方毫不值得留恋。可如今经历了两次人生之后，我才发现自由并不是我唯一向往的东西，看到那些教徒们得知将获得救赎时，那满怀赤诚、希望与感激的样子，才是圣子这个身份真正的意义。",
    AwakerVoiceResAffix = "GossipFavorite",
    Sort = 39
  },
